class Solution {
public:
    int subarrayLCM(std::vector<int>& nums, int k) {
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            long long cur = nums[i];
            for (int j = i; j < n; ++j) {
                cur = std::lcm(cur, (long long)nums[j]);
                if (cur == k) ans++;
                else if (cur > k) break;
            }
        }
        return ans;
    }
};

class Solution {
    public int subarrayLCM(int[] nums, int k) {
        int n = nums.length;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            long cur = nums[i];
            for (int j = i; j < n; j++) {
                cur = lcm(cur, nums[j]);
                if (cur == k) ans++;
                else if (cur > k) break;
            }
        }
        return ans;
    }
    private long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
    private long lcm(long a, long b) {
        return (a * b) / gcd(a, b);
    }
}

var subarrayLCM = function(nums, k) {
    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    const lcm = (a, b) => (a * b) / gcd(a, b);
    const n = nums.length;
    let ans = 0;
    for (let i = 0; i < n; i++) {
        let cur = nums[i];
        for (let j = i; j < n; j++) {
            cur = lcm(cur, nums[j]);
            if (cur === k) ans++;
            else if (cur > k) break;
        }
    }
    return ans;
};
